@Component("brandSafetyPolicy-subscriber")
public class BrandSafetyPolicySubscriber extends BaseSubscriber {

	public BrandSafetyPolicySubscriber() {
	}
	
    public SubscriptionQueryResult<List<BrandSafetyPolicy>, BrandSafetyPolicy> brandSafetyPolicySubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllBrandSafetyPolicyQuery(), 
                		ResponseTypes.multipleInstancesOf(BrandSafetyPolicy.class),
                		ResponseTypes.instanceOf(BrandSafetyPolicy.class));
    }

    public SubscriptionQueryResult<BrandSafetyPolicy, BrandSafetyPolicy> brandSafetyPolicySubscribe(@DestinationVariable UUID brandSafetyPolicyId) {
        return queryGateway
                .subscriptionQuery(new FindBrandSafetyPolicyQuery(new LoadBrandSafetyPolicyFilter(brandSafetyPolicyId)), 
                		ResponseTypes.instanceOf(BrandSafetyPolicy.class),
                		ResponseTypes.instanceOf(BrandSafetyPolicy.class));
    }





}

